@startuml

class University {}

class Department {}

class ResearchGroup {
  + groupName : string
}

class Researcher {
  + researcherId : int
  + name : string
}

class Project {
  + projectId : int
  + title : string
}

class WorkPackage {
  + wpId : int
  + description : string
}

Department "1" -- "*" ResearchGroup
ResearchGroup "1" -- "*" Researcher
ResearchGroup "1" -- "*" WorkPackage : leads
Project "1" *-- "1..*" WorkPackage
WorkPackage "*" -- "*" Researcher : teamMember

@enduml

